const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(cors());

const server = http.createServer(app);

// รองรับทั้ง localhost ตอนเทส และรองรับ Vercel ในอนาคต
const io = new Server(server, {
    cors: {
        origin: "https://tlma-eosin.vercel.app/", 
        methods: ["GET", "POST"]
    }
});

// กำหนดตำแหน่งไฟล์ CSV โดยอิงจากภาพโครงสร้างโฟลเดอร์ของคุณ
// ไฟล์อยู่ที่: forecast-app/public/ping_result.csv
const csvPath = 'C:\\Users\\Wuttikorn\\Documents\\TLF\\forecast-app\\public\\ping_result.csv';

// ฟังก์ชันสำหรับอ่านและแปลง CSV เป็น JSON Object ที่เข้าคู่กับหน้าจอของคุณ
const parsePingCSV = () => {
    try {
        if (!fs.existsSync(csvPath)) {
            console.log("ยังไม่พบไฟล์ CSV ที่ตำแหน่ง:", csvPath);
            return [];
        }

        const text = fs.readFileSync(csvPath, 'utf-8');
        const blocks = text.split(/={30,}/).filter(b => b.trim() !== "");

        const parsedNodes = blocks.map(block => {
            const getValue = (key) => {
                const line = block.split('\n').find(l => l.trim().startsWith(key));
                // แก้ไข: ใส่ [1] หลังแยกสัญลักษณ์ : เพื่อเอาค่าหลังข้อความตัวแปรมาใช้จริง
                if (line && line.includes(':')) {
                    const parts = line.split(':');
                    return parts.slice(1).join(':').trim(); 
                }
                return "";
            };

            const desc = getValue("Description") || "ทั่วไป#อุปกรณ์";
            const ip = getValue("IP Address") || "0.0.0.0";
            
            const [stadium, device] = desc.includes("#") ? desc.split("#") : ["ทั่วไป", desc];
            const status = getValue("Last Ping Status") === "Succeeded" ? "ONLINE" : "TIMEOUT";
            const ping = getValue("Last Ping Time") || "0";

            return { group: stadium?.trim(), name: device?.trim(), ip, status, ping };
        });

        return parsedNodes;
    } catch (error) {
        console.error("เกิดข้อผิดพลาดในการอ่านไฟล์ CSV:", error);
        return [];
    }
};



io.on('connection', (socket) => {
    console.log('Frontend เชื่อมต่อเข้ามาแล้ว:', socket.id);

    // 1. ส่งข้อมูลล่าสุดให้ Frontend ทันทีที่กดเชื่อมต่อเข้ามาครั้งแรก (ไม่ต้องรอลูป)
    const initialData = parsePingCSV();
    socket.emit('ping-update', initialData);

    // 2. ตั้งเวลาให้อ่านไฟล์และส่งข้อมูลใหม่ไปให้ทุกๆ 2 วินาที (ปรับเปลี่ยนเวลาได้ตามต้องการ)
    const intervalId = setInterval(() => {
        const updatedData = parsePingCSV();
        socket.emit('ping-update', updatedData);
    }, 2000); 

    socket.on('disconnect', () => {
        clearInterval(intervalId); // เคลียร์ลูปเพื่อคืนทรัพยากรเมื่อปิดหน้าเว็บ
        console.log('Frontend ตัดการเชื่อมต่อ');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log(`Backend ระบบแชร์ข้อมูล Ping รันสำเร็จที่พอร์ต: ${PORT}`));
